#!/usr/bin/env python3
"""Build the guide character's sprite assets from images generated by Meta's Muse Image.

Inputs (a folder): base.png plus closed.png, ah.png, oh.png, ee.png, blink.png. They are edits of the same character
on a flat green (#00FF00) background (see docs/GUIDE_CHARACTER.md for the prompts). The mouth and eye regions were
located on base.png with SAM 3.1; those boxes are the constants below (as fractions of the head crop).

Output (app/android/app/src/main/res): drawable-nodpi/guide_*.png and raw/guide_sprite.json.
Only the small face patches change while the guide talks or blinks, so hair and clothes never jitter between frames.

    python scripts/build_guide_sprites.py <variants_dir>
"""
import json
import os
import sys

import numpy as np
from PIL import Image, ImageFilter

HEAD_CROP = (256, 0, 768, 461)                        # head area of the 1024 x 1536 base image (x 25-75%, y 0-30%)
MOUTH = (0.453, 0.521, 0.564, 0.557)                  # SAM 3.1 box for "mouth", fractions of HEAD_CROP
EYES = (0.398, 0.389, 0.583, 0.464)                   # SAM 3.1 box for "eyes"
OUT_H = 760                                           # sprite height in pixels
RES = os.path.join(os.path.dirname(__file__), "..", "app", "android", "app", "src", "main", "res")


def to_full(box, pad_x, pad_y):
    cx0, cy0, cx1, cy1 = HEAD_CROP
    w, h = cx1 - cx0, cy1 - cy0
    x0, y0, x1, y1 = cx0 + box[0] * w, cy0 + box[1] * h, cx0 + box[2] * w, cy0 + box[3] * h
    return (int(x0 - pad_x), int(y0 - pad_y), int(x1 + pad_x), int(y1 + pad_y))


def chroma_key(img):
    """Green screen -> transparent, with the green spill removed from the soft edge pixels."""
    a = np.asarray(img.convert("RGB")).astype(np.float32)
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    greenness = g - np.maximum(r, b)
    alpha = np.clip(1.0 - (greenness - 30.0) / 70.0, 0.0, 1.0)
    g2 = np.where(alpha < 0.98, np.minimum(g, np.maximum(r, b)), g)          # despill: no edge pixel may be greener than its red/blue
    keep = (alpha > 0.02)[..., None]
    rgb = np.where(keep, np.dstack([r, g2, b]), 0.0)                          # transparent pixels carry no colour that could bleed
    out = np.dstack([rgb, alpha * 255.0]).astype(np.uint8)
    return Image.fromarray(out, "RGBA")


def align(base, var, exclude, search=10):
    """Best (dx, dy) to shift `var` onto `base`, judged on the head area outside the regions that are meant to differ."""
    x0, y0, x1, y1 = HEAD_CROP
    b = np.asarray(base.convert("L")).astype(np.float32)[y0:y1, x0:x1]
    v = np.pad(np.asarray(var.convert("L")).astype(np.float32), search, mode="edge")   # the head may touch the image edge
    mask = np.ones_like(b, dtype=bool)
    for (ex0, ey0, ex1, ey1) in exclude:
        mask[max(0, ey0 - y0):max(0, ey1 - y0), max(0, ex0 - x0):max(0, ex1 - x0)] = False
    best, bd = (0, 0), 1e18
    for dy in range(-search, search + 1):
        for dx in range(-search, search + 1):
            s = v[search + y0 + dy:search + y1 + dy, search + x0 + dx:search + x1 + dx]
            d = np.abs(s - b)[mask].mean()
            if d < bd:
                bd, best = d, (dx, dy)
    return best


def patch(base, var, box, feather=14):
    """A feathered RGBA patch of `var` over `box`, after aligning var to base.
    The patch is green-keyed too: the gaps between chin and headset show background, which must stay transparent."""
    shift = align(base, var, [box])
    x0, y0, x1, y1 = box
    crop = chroma_key(var).crop((x0 + shift[0], y0 + shift[1], x1 + shift[0], y1 + shift[1]))
    mask = Image.new("L", crop.size, 0)
    inner = Image.new("L", (crop.width - 2 * feather, crop.height - 2 * feather), 255)
    mask.paste(inner, (feather, feather))
    mask = mask.filter(ImageFilter.GaussianBlur(feather / 2.2))
    alpha = np.minimum(np.asarray(mask).astype(np.float32), np.asarray(crop.getchannel("A")).astype(np.float32))
    crop.putalpha(Image.fromarray(alpha.astype(np.uint8), "L"))
    return crop, shift


def main(src):
    ld = lambda n: Image.open(os.path.join(src, n + ".png")).convert("RGB").resize((1024, 1536))
    base, vars_ = ld("base"), {n: ld(n) for n in ("closed", "ah", "oh", "ee", "blink")}

    keyed = chroma_key(base)
    bbox = keyed.getchannel("A").point(lambda v: 255 if v > 12 else 0).getbbox()
    pad = 14
    bbox = (max(0, bbox[0] - pad), max(0, bbox[1] - pad), min(1024, bbox[2] + pad), min(1536, bbox[3] + pad))
    s = OUT_H / (bbox[3] - bbox[1])
    sprite = keyed.crop(bbox)
    sprite = sprite.convert("RGBa").resize((round(sprite.width * s), OUT_H), Image.LANCZOS).convert("RGBA")

    d = os.path.join(RES, "drawable-nodpi")
    os.makedirs(d, exist_ok=True)
    os.makedirs(os.path.join(RES, "raw"), exist_ok=True)
    sprite.save(os.path.join(d, "guide_base.png"), optimize=True)

    mouth_box = to_full(MOUTH, 34, 30)       # room for an open mouth, chin and cheeks
    eyes_box = to_full(EYES, 16, 16)
    meta = {"w": sprite.width, "h": sprite.height, "patches": {}}

    def place(name, box, var):
        p, shift = patch(base, var, box)
        px = round((box[0] - bbox[0]) * s); py = round((box[1] - bbox[1]) * s)
        p = p.convert("RGBa").resize((round(p.width * s), round(p.height * s)), Image.LANCZOS).convert("RGBA")
        p.save(os.path.join(d, f"guide_{name}.png"), optimize=True)
        meta["patches"][name] = {"x": px, "y": py, "w": p.width, "h": p.height}
        print(f"{name:12} shift={shift}  at ({px},{py}) size {p.width}x{p.height}")

    for n in ("closed", "ah", "oh", "ee"):
        place("mouth_" + n, mouth_box, vars_[n])
    place("eyes_blink", eyes_box, vars_["blink"])
    meta["mouth_anchor"] = {"cx": meta["patches"]["mouth_closed"]["x"] + meta["patches"]["mouth_closed"]["w"] / 2,
                            "cy": meta["patches"]["mouth_closed"]["y"] + meta["patches"]["mouth_closed"]["h"] / 2}
    json.dump(meta, open(os.path.join(RES, "raw", "guide_sprite.json"), "w"), indent=1)
    print("sprite", sprite.size, "->", os.path.relpath(d))


if __name__ == "__main__":
    main(sys.argv[1])
